        counts = {}
        for r in range(h):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
        if max(counts.values()) >= h - 3:
            stripe_cols.append(c)

    def select_indices(size, stripes):
        selected = []
        start = 0
        for s in stripes:
            if start < s:
                selected.append(start)
            selected.append(s)
            start = s + 1
        if start < size:
            selected.append(start)
        return selected

    rows = select_indices(h, stripe_rows)
    cols = select_indices(w, stripe_cols)
    return [[grid[r][c] for c in cols] for r in rows]
